SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS medicine_catalogue;

CREATE TABLE medicine_catalogue (
    id                  INT NOT NULL AUTO_INCREMENT,
    sl_no               INT NOT NULL,
    medicine_name       VARCHAR(255) NOT NULL,
    strength            VARCHAR(100) DEFAULT NULL,
    composition         TEXT DEFAULT NULL,
    dosage_form         VARCHAR(100) DEFAULT NULL,
    pack_quantity       INT DEFAULT NULL,
    why_used            TEXT DEFAULT NULL,
    description         TEXT DEFAULT NULL,
    order_quantity      INT NOT NULL DEFAULT 1,
    selling_price       DECIMAL(10,2) DEFAULT NULL,
    stock               INT DEFAULT NULL,
    prescription_status VARCHAR(100) DEFAULT 'Not specified in source',
    status              TINYINT(1) NOT NULL DEFAULT 1,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
                        ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uq_med_slno (sl_no),
    KEY idx_med_name (medicine_name),
    KEY idx_med_form (dosage_form),
    KEY idx_med_strength (strength),
    KEY idx_med_status (status),
    FULLTEXT KEY ft_med_search (medicine_name, composition, why_used)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

